From 7480585d03b8061bbf7d83d5621bbd2119619099 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 18:54:44 +0100
Subject: [PATCH] libtaskmanager: sort windows inside a group by title in
 alphabetical mode

With alphabetical sorting, all windows in a group share the same app name,
so they were listed in the order they were opened. Sort them by their
window title instead, keeping opening order only for identical titles.

BUG: 422704
---
 libtaskmanager/tasksmodel.cpp | 12 ++++++++++++
 1 file changed, 12 insertions(+)

diff --git a/libtaskmanager/tasksmodel.cpp b/libtaskmanager/tasksmodel.cpp
index fd6246a363..dd61099d67 100644
--- a/libtaskmanager/tasksmodel.cpp
+++ b/libtaskmanager/tasksmodel.cpp
@@ -888,6 +888,18 @@ bool TasksModel::Private::lessThan(const QModelIndex &left, const QModelIndex &r
     case SortAlpha:
     // fall through
     default: {
+        // Windows inside a group all belong to the same app, so sort them by
+        // their title instead.
+        if (sortMode == SortAlpha && left.parent().isValid() && left.parent() == right.parent()) {
+            const int titleSortResult = left.data(Qt::DisplayRole).toString().localeAwareCompare(right.data(Qt::DisplayRole).toString());
+
+            if (titleSortResult != 0) {
+                return (titleSortResult < 0);
+            }
+
+            return (left.row() < right.row());
+        }
+
         // The overall goal of alphabetic sorting is to sort tasks belonging to the
         // same app together, while sorting the resulting sets alphabetically among
         // themselves by the app name. The following code tries to achieve this by
